-- Stores department information for acceptance processing
CREATE TABLE IF NOT EXISTS "acceptance_departments" (
  "id" INTEGER PRIMARY KEY,
  "name" VARCHAR(255) NOT NULL UNIQUE,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "idx_acceptance_departments_name" ON "acceptance_departments"("name");

-- Stores staff member details and their associated department
CREATE TABLE IF NOT EXISTS "acceptance_staff" (
  "id" INTEGER PRIMARY KEY,
  "department_id" INT NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "monthly_inr_salary" DECIMAL(12,2) NOT NULL,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "fk_acceptance_staff_department_id" FOREIGN KEY ("department_id") REFERENCES "acceptance_departments"("id")
);

CREATE INDEX IF NOT EXISTS "idx_acceptance_staff_department_id" ON "acceptance_staff"("department_id");
